import React, { useState } from "react";
import axios from "axios";
import { useHistory } from "react-router-dom";

function Login() {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");

  let history = useHistory();

  const login = () => {
    if (!username || !password) {
      setError("Please enter both username and password");
      return;
    }

    const data = { username: username, password: password };
    
    axios
      .post("http://localhost:3003/auth/login", data) // تم التغيير من 3001 إلى 3003
      .then((response) => {
        if (response.data.error) {
          setError(response.data.error);
        } else {
          sessionStorage.setItem("accesstoken", response.data);
          history.push("/");
        }
      })
      .catch((error) => {
        console.error("Login error:", error);
        if (error.code === "ERR_NETWORK") {
          setError("Cannot connect to server. Please make sure the backend is running on port 3003"); // تم تغيير الرسالة
        } else if (error.response) {
          setError(error.response.data.error || "Login failed");
        } else {
          setError("An unexpected error occurred");
        }
      });
  };

  return (
    <div className="loginContainer">
      {error && <div className="errorMessage" style={{ color: "red" }}>{error}</div>}
      
      <label>Username:</label>
      <input
        type="text"
        onChange={(event) => {
          setUsername(event.target.value);
        }}
      />
      
      <label>Password:</label>
      <input
        type="password"
        onChange={(event) => {
          setPassword(event.target.value);
        }}
        onKeyPress={(event) => {
          if (event.key === "Enter") {
            login();
          }
        }}
      />

      <button onClick={login}>Login</button>
    </div>
  );
}

export default Login;
